## ---- 01: Memory-Optimized Batch Processing  (qmd line 81) ---------------------------

# The streaming aggregation pattern
cf_pool_path <- matrix(0, nrow = n_paths, ncol = n_months)

# Per-loan projection, vectorized over paths, via oasr primitives
# (column 9 of the oasr cashflow array is the total cashflow)
project_single_loan_all_paths <- function(loan_i, rate_paths, prepay_mod) {
  cv <- calculate_credit_vectors(loan_i, rate_paths, prepay_mod)
  cf <- project_cashflows(loan_i, cv)
  t(sapply(cf, function(x) x[, 9, 1]))   # [n_paths x n_months]
}

for (i in seq_len(n_loans)) {
  loan_i <- pool_assets[i, , drop = FALSE]
  cf_loan_path <- project_single_loan_all_paths(loan_i, rate_paths,
                                                prepay_mod)
  # Accumulate into pool-level aggregate
  cf_pool_path <- cf_pool_path + cf_loan_path
}


## ---- 02: Vectorization Over Paths  (qmd line 114) ------------------------------------

# pmt for all paths at once
pmt_paths <- B_t_paths * (c_paths / 12) / (1 - (1 + c_paths / 12)^(-tau))
I_paths   <- B_t_paths * c_paths / 12
psched    <- pmt_paths - I_paths
VP_paths  <- (B_t_paths - psched) * SMM_paths
D_paths   <- (B_t_paths - psched) * MDR_paths
P_paths   <- psched * (1 - SMM_paths - MDR_paths)
B_next    <- B_t_paths - P_paths - VP_paths - D_paths


## ---- 03: Parallelization Patterns  (qmd line 131) ------------------------------------

library(future.apply)
plan(multisession, workers = 8)

cf_pool_path <- Reduce("+", future_lapply(seq_len(n_loans), function(i) {
  project_single_loan_all_paths(pool_assets[i, , drop = FALSE],
                                rate_paths, prepay_mod)
}))


