library(dplyr)

loan_tape <- read.csv("data/sample_loan_tape.csv") %>%
  filter(current_balance > 0)

pool_summaries <- loan_tape %>%
  summarize(
    total_balance = sum(current_balance),
    WAC  = weighted.mean(coupon, current_balance),
    WAM  = weighted.mean(remaining_term, current_balance),
    WALA = weighted.mean(seasoning, current_balance)
  )
pool_summaries


## ---- 05: Stratification by Coupon Stack  (qmd line 229) ------------------------------

loan_tape %>%
  mutate(coupon_bucket = cut(coupon,
                              breaks = seq(0.075, 0.115, by = 0.005))) %>%
  group_by(coupon_bucket) %>%
  summarize(balance = sum(current_balance),
            n_loans = n(),
            pct = balance / sum(loan_tape$current_balance))


