library(future.apply)
plan(multisession, workers = 8)

# Helper: parallel per-loan projection driven by oasr primitives
per_loan_cf <- function(i) {
  ad <- pool_assets[i, , drop = FALSE]
  cv <- calculate_credit_vectors(ad, rate_paths, prepay_mod)
  project_cashflows(ad, cv,
                    reference_rates = extract_reference_rates(rate_paths))[[1]]
}
loan_cfs_par <- future_lapply(seq_len(nrow(pool_assets)), per_loan_cf)


## ---- 08: Representative-Line Approximation (User Helper)  (qmd line 269) -------------

# Helper: synthetic single-loan asset built from WAC/WAM/WALA
# (columns follow the oasr asset_data convention)
build_rep_line <- function(assets) {
  data.frame(
    asset_id  = "REP_LINE",
    balance   = sum(assets$balance),
    wac       = with(assets, weighted.mean(wac, balance)),
    term      = with(assets, round(weighted.mean(term, balance))),
    age       = with(assets, round(weighted.mean(age, balance))),
    servicing = with(assets, weighted.mean(servicing, balance))
  )
}

rep_asset <- build_rep_line(pool_assets)
rep_cv    <- calculate_credit_vectors(rep_asset, rate_paths, prepay_mod)
rep_cf    <- project_cashflows(rep_asset, rep_cv,
                                reference_rates = ref_rates)


## ---- 09: Convergence Diagnostic  (qmd line 291) --------------------------------------

running_mean <- function(npv_paths) cumsum(npv_paths) / seq_along(npv_paths)
running_se   <- function(npv_paths) {
  sapply(seq_along(npv_paths), function(p)
    sd(npv_paths[1:p]) / sqrt(p))
}

library(ggplot2)
conv_df <- data.frame(path = seq_along(npv_paths),
                      mean = running_mean(npv_paths),
                      se   = running_se(npv_paths))
ggplot(conv_df, aes(path, mean)) +
  geom_line() +
  labs(x = "Paths", y = "Running mean") +
  theme_minimal()

ggplot(conv_df, aes(path, se)) +
  geom_line() +
  scale_x_log10() +
  scale_y_log10() +
  geom_abline(intercept = 0, slope = -0.5,
              colour = "red") +   # expected -1/2 slope
  labs(x = "Paths (log)", y = "Running SE (log)") +
  theme_minimal()


